def compute(vars):
    industrial_packaging_sales = vars["v1"]
    containerboard_sales = vars["v2"]

    if industrial_packaging_sales == 0:
        return {"value": None, "trace": {"output_meta": {"currency": None, "scale": None, "unit": "percentage"}}}

    ratio = containerboard_sales / industrial_packaging_sales
    percentage = ratio * 100

    return {
        "value": percentage,
        "trace": {
            "ratio": ratio,
            "output_meta": {"currency": None, "scale": None, "unit": "percentage"},
        },
    }
